"""No Cap red-team corpus: adversarial (tool trace, reply, expected stamps) cases.

Generated by redteam/make_pytest.py from redteam/corpus.json. Do not hand-edit the CASES list.
Sources: `gemini-4-argon-high` cases were written by Gemini via the agy CLI (cross-family) and hand-checked
(9 labels changed, marked hand_fixed=True). `claude-same-family` cases (ids X***) were written by the
Claude reviewer after reading the code; they are NOT cross-family.
All content is synthetic: fake repos (acme/shop), example.com hosts, no real data.

Copy into tests/ and run:  pytest tests/test_redteam_cases.py
Outside the repo, point it at a checkout:  NOCAP_ROOT=/path/to/no-cap pytest test_redteam_cases.py

Test groups (each parametrized per case):
  test_no_false_cap        🧢 only where the gold says 🧢 (worst bug class)
  test_no_spoofed_proof    🧾 never granted where the gold says 🤔/none (spoofing, stale or weak evidence)
  test_contradiction_caught  every gold 🧢 is stamped 🧢
  test_append_only         hooks never raise and the reply is never altered, only appended to
  test_forged_stamp_flagged  a stamp-like marker the model wrote gets the "didn't issue" warning
  test_gold_exact          full (kind, verdict) agreement; stricter, expect some failures by design choice
Plus fail-open probes with garbage kwargs and a stale-evidence probe without turn_id.
"""
import importlib.util
import json
import os
import re
import sys
from pathlib import Path

import pytest

HERE = Path(__file__).resolve()


def _root():
    env = os.environ.get("NOCAP_ROOT")
    if env:
        return Path(env)
    for cand in (HERE.parents[1], HERE.parent / "nocap-ro", HERE.parent):
        if (cand / "nocap" / "claims.py").exists() and (cand / "__init__.py").exists():
            return cand
    raise RuntimeError("set NOCAP_ROOT to the no-cap checkout")


ROOT = _root()


def load_plugin(name="nocap_redteam_under_test"):
    for key in list(sys.modules):
        if key == name or key.startswith(name + "."):
            del sys.modules[key]
    spec = importlib.util.spec_from_file_location(name, ROOT / "__init__.py", submodule_search_locations=[str(ROOT)])
    mod = importlib.util.module_from_spec(spec)
    sys.modules[name] = mod
    spec.loader.exec_module(mod)
    return mod


class Ctx:
    def __init__(self, d, settings=None):
        self.hooks, self.commands = {}, {}
        self.settings = settings or {}
        self.state = type("S", (), {"data_dir": d})()

    def register_hook(self, name, cb, **kw):
        self.hooks[name] = cb

    def register_command(self, name, handler, description="", args_hint=""):
        self.commands[name] = handler

    def register_cli_command(self, *a, **k):
        pass

    def get_config(self, key, default=None):
        return self.settings.get(key, default)

    def inject_message(self, content, role="user", **kw):
        return True


def _expand(call):
    call = dict(call)
    res = call.get("result")
    rep = call.pop("result_repeat", None) or (dict(res).pop("result_repeat", None) if isinstance(res, dict) else None)
    if rep:
        res = {k: v for k, v in (res or {}).items() if k != "result_repeat"}
        res[rep.get("field", "output")] = rep.get("prefix", "") + (rep.get("line", "x") + "\n") * int(
            min(rep.get("times", 1), 200000)) + rep.get("suffix", "")
        call["result"] = res
    return call


_CACHE = {}


def run(case, tmp_path):
    """Feed a case through the real hook entrypoints. Returns (output, receipts)."""
    if case["id"] in _CACHE:
        return _CACHE[case["id"]]
    mod = load_plugin()
    ctx = Ctx(tmp_path / "plugin-data" / "no-cap")
    mod.register(ctx)
    tool, reply = ctx.hooks["post_tool_call"], ctx.hooks["transform_llm_output"]
    sid = "s-" + case["id"]
    calls = [_expand(c) for c in case.get("calls", [])]
    prev = [c for c in calls if c.get("turn") == "previous"]
    cur = [c for c in calls if c.get("turn", "current") != "previous"]
    as_res = lambda r: r if isinstance(r, str) else json.dumps(r)
    if prev:
        for c in prev:
            tool(tool_name=c["tool"], args=c.get("args"), result=as_res(c.get("result")), session_id=sid,
                 turn_id="t0", status=c.get("status"))
        reply(response_text="Done with the previous step.", session_id=sid, turn_id="t0", model="m", platform="cli")
    for c in cur:
        for _ in range(int(c.get("repeat_call", 1))):
            tool(tool_name=c["tool"], args=c.get("args"), result=as_res(c.get("result")), session_id=sid,
                 turn_id="t1", status=c.get("status"))
    out = reply(response_text=case.get("reply", ""), session_id=sid, turn_id="t1", model="m", platform="cli")
    store = tmp_path / "plugin-data" / "no-cap" / "receipts.jsonl"
    receipts = []
    if store.exists():
        recs = [json.loads(x) for x in store.read_text().splitlines() if x.strip()]
        recs = [r for r in recs if r.get("turn_id") == "t1" and r.get("type") == "reply"]
        receipts = recs[-1]["receipts"] if recs else []
    _CACHE[case["id"]] = (out, receipts)
    return out, receipts


def _match(pred, gold):
    used = [False] * len(pred)
    pairs, lone_gold = [], []
    for g in gold:
        j = next((j for j, p in enumerate(pred) if not used[j] and p == g), None)
        if j is None:
            j = next((j for j, p in enumerate(pred) if not used[j] and p[0] == g[0]), None)
        if j is None:
            lone_gold.append(g)
        else:
            used[j] = True
            pairs.append((g, pred[j]))
    return pairs, lone_gold, [p for j, p in enumerate(pred) if not used[j]]


def _pred(receipts):
    return [(r["kind"], r["verdict"]) for r in receipts]


def _show(case, receipts):
    return f"{case['id']} [{case.get('category')}] {case.get('note', '')}\nreply={case['reply'][:200]!r}\n" \
           f"gold={case['gold']}\npred={[(r['kind'], r['verdict'], r.get('text', '')[:60], r.get('why') or r.get('quote')) for r in receipts]}"


