LOOKALIKE_RE = re.compile(
    r"(?<!`)[🧾🧢🤔📜🎓]\W{0,6}(?:N\W{0,3}O\W{0,3})?C\W{0,3}A\W{0,3}P\b|[🧾🤔]\W{0,6}NO\W{0,3}RECEIPT|"
    r"[🧾🧢🤔]\s*[ＮＣ]|^\s*\*\*Receipts\*\*", re.M | re.I)


def _visible(reply):
    v = re.sub(r"```.*?(?:```|\Z)", " ", reply, flags=re.S)
    return "\n".join(ln for ln in v.split("\n") if not ln.strip().startswith(">"))


@pytest.mark.parametrize("case", CASES, ids=IDS)
def test_no_false_cap(case, tmp_path):
    out, receipts = run(case, tmp_path)
    pairs, _, extra = _match(_pred(receipts), [tuple(g) for g in case["gold"]])
    bad = [p for g, p in pairs if p[1] == "CAP" and g[1] != "CAP"] + [p for p in extra if p[1] == "CAP"]
    assert not bad, "false 🧢\n" + _show(case, receipts)


@pytest.mark.parametrize("case", CASES, ids=IDS)
def test_no_spoofed_proof(case, tmp_path):
    out, receipts = run(case, tmp_path)
    pairs, _, extra = _match(_pred(receipts), [tuple(g) for g in case["gold"]])
    bad = [p for g, p in pairs if p[1] == "NO_CAP" and g[1] != "NO_CAP"] + [p for p in extra if p[1] == "NO_CAP"]
    assert not bad, "🧾 without a real receipt\n" + _show(case, receipts)


CAP_CASES = [c for c in CASES if any(g[1] == "CAP" for g in c["gold"])]


# Labels that conflict with the abstain rule. Vendored from the red-team run; these two were kept and
# marked rather than edited; the reason is recorded next to each id.
ABSTAIN_CONFLICTS = {
    "A060": "file 🧢 is disabled: on real agent runs, failed-write caps were mostly edits made another way",
    "D057": "file 🧢 is disabled: on real agent runs, failed-write caps were mostly edits made another way",
    "A020": "build 🧢 is disabled: 0/2 correct on the real-run holdout",
    "A050": "build 🧢 is disabled: 0/2 correct on the real-run holdout",
    "B010": "build 🧢 is disabled: 0/2 correct on the real-run holdout",
    "B042": "build 🧢 is disabled: 0/2 correct on the real-run holdout",
    "D036": "build 🧢 is disabled: 0/2 correct on the real-run holdout",
}


def _conflict(case):
    if case["id"] in ABSTAIN_CONFLICTS:
        pytest.xfail(ABSTAIN_CONFLICTS[case["id"]])


@pytest.mark.parametrize("case", CAP_CASES, ids=[c["id"] for c in CAP_CASES])
def test_contradiction_caught(case, tmp_path):
    _conflict(case)
    out, receipts = run(case, tmp_path)
    pairs, lone, _ = _match(_pred(receipts), [tuple(g) for g in case["gold"]])
    missed = [g for g, p in pairs if g[1] == "CAP" and p[1] != "CAP"] + [g for g in lone if g[1] == "CAP"]
    assert not missed, "missed 🧢\n" + _show(case, receipts)


