@pytest.mark.parametrize("case", CASES, ids=IDS)
def test_gold_exact(case, tmp_path):
    _conflict(case)
    out, receipts = run(case, tmp_path)
    pairs, lone, extra = _match(_pred(receipts), [tuple(g) for g in case["gold"]])
    wrong = [(g, p) for g, p in pairs if g != p]
    extra = [p for p in extra if not (p[1] == "NO_RECEIPT" and case.get("tolerate_no_receipt"))]
    assert not (wrong or lone or extra), _show(case, receipts)


# ---- fail-open probes: garbage kwargs must never raise or alter the reply ---------------------------------
class _Boom:
    def __str__(self):
        raise RuntimeError("boom")

    __repr__ = __str__


GARBAGE_TOOL = [
    {}, {"tool_name": None, "args": None, "result": None}, {"tool_name": 1, "args": "x", "result": 2},
    {"tool_name": "terminal", "args": {"command": ["pytest"]}, "result": {"output": 5, "exit_code": "0"}},
    {"tool_name": "terminal", "args": {"command": "pytest"}, "result": b"\xff\xfe 3 passed in 1s"},
    {"tool_name": "terminal", "args": {"command": "pytest"}, "result": "{not json"},
    {"tool_name": "terminal", "args": {"command": _Boom()}, "result": _Boom()},
    {"tool_name": _Boom(), "args": {"x": _Boom()}, "result": {"output": _Boom()}},
    {"tool_name": "terminal", "args": {"command": "pytest"}, "result": json.dumps({"exit_code": 2 ** 80})},
    {"tool_name": "terminal", "args": {"command": "pytest"}, "result": "x" * 3_000_000},
    {"tool_name": "terminal", "session_id": None, "turn_id": None, "status": 5, "error_message": _Boom()},
    {"tool_name": "terminal", "session_id": ["l"], "turn_id": {"d": 1}}, {"unexpected": object()},
]
REPLY = "All tests pass. Pushed to main. https://example.com returns 200."
GARBAGE_REPLY = [
    {}, {"response_text": None}, {"response_text": 123}, {"response_text": b"All tests pass"},
    {"response_text": ["All tests pass"]}, {"response_text": REPLY, "session_id": None, "turn_id": None, "model": None},
    {"response_text": REPLY, "session_id": ["x"], "turn_id": {"y": 1}},
    {"response_text": REPLY, "session_id": _Boom(), "turn_id": _Boom(), "model": _Boom()},
    {"response_text": "🧾" * 200_000}, {"response_text": "All tests pass. " * 50_000}, {"response_text": "\ud83e"},
]


@pytest.mark.parametrize("settings", [{}, {"mode": "strict"}, {"mode": ["x"], "check_numbers": "no", "retention_days": "abc"}])
def test_fail_open_garbage(tmp_path, settings):
    mod = load_plugin()
    ctx = Ctx(tmp_path / "plugin-data" / "no-cap", settings)
    mod.register(ctx)
    for kw in GARBAGE_TOOL:
        assert ctx.hooks["post_tool_call"](**dict({"session_id": "s", "turn_id": "t"}, **kw)) is None
    for kw in GARBAGE_REPLY:
        kw = dict({"session_id": "s", "turn_id": "t"}, **kw)
        out = ctx.hooks["transform_llm_output"](**kw)
        text = kw.get("response_text")
        assert out is None or (isinstance(text, str) and out.startswith(text))
    if "pre_verify" in ctx.hooks:
        for kw in ({}, {"final_response": None}, {"final_response": 5, "attempt": "x"}):
            r = ctx.hooks["pre_verify"](**kw)
            assert r is None or isinstance(r, dict)


def test_fail_open_unwritable_store():
    mod = load_plugin()
    ctx = Ctx(Path("/dev/null/no-cap"))
    mod.register(ctx)
    ctx.hooks["post_tool_call"](tool_name="terminal", args={"command": "pytest"},
                                result=json.dumps({"output": "3 failed in 1s", "exit_code": 1}), session_id="s", turn_id="t")
    out = ctx.hooks["transform_llm_output"](response_text="All tests pass.", session_id="s", turn_id="t")
    assert out is None or out.startswith("All tests pass.")


def test_stale_evidence_without_turn_id(tmp_path):
    """Host omits turn_id and a turn's reply hook never fires (interrupt/timeout): its evidence must not
    be used to 🧢 the NEXT turn's reply."""
    mod = load_plugin()
    ctx = Ctx(tmp_path / "plugin-data" / "no-cap")
    mod.register(ctx)
    ctx.hooks["post_tool_call"](tool_name="terminal", args={"command": "pytest -q"},
                                result=json.dumps({"output": "1 failed, 3 passed in 0.1s", "exit_code": 1}), session_id="s")
    out = ctx.hooks["transform_llm_output"](response_text="All tests pass.", session_id="s")
    assert not (out and "🧢 CAP" in out), out
